function toNumber(v: number | InstanceType<typeof DecimalShim>): number {
  return typeof v === "number" ? v : v.toNumber();
}

/// A minimal stand-in for Prisma.Decimal — enough arithmetic for lib/billing.ts
/// and lib/api.ts's invoice-total math, not a general decimal library.
class DecimalShim {
  private readonly value: number;

  constructor(input: number | string) {
    this.value = typeof input === "string" ? parseFloat(input) : input;
  }

  add(other: number | DecimalShim) {
    return new DecimalShim(this.value + toNumber(other));
  }
  sub(other: number | DecimalShim) {
    return new DecimalShim(this.value - toNumber(other));
  }
  mul(other: number | DecimalShim) {
    return new DecimalShim(this.value * toNumber(other));
  }
  greaterThan(other: number | DecimalShim) {
    return this.value > toNumber(other);
  }
  greaterThanOrEqualTo(other: number | DecimalShim) {
    return this.value >= toNumber(other);
  }
  toNumber() {
    return this.value;
  }
  toString() {
    return this.value.toFixed(2);
  }
}

class PrismaClientKnownRequestErrorShim extends Error {
  readonly code: string;
  readonly clientVersion: string;
  readonly meta?: Record<string, unknown>;

  constructor(message: string, opts: { code: string; clientVersion: string; meta?: Record<string, unknown> }) {
    super(message);
    this.name = "PrismaClientKnownRequestError";
    this.code = opts.code;
    this.clientVersion = opts.clientVersion;
    this.meta = opts.meta;
  }
}

export const Prisma = {
  Decimal: DecimalShim,
  PrismaClientKnownRequestError: PrismaClientKnownRequestErrorShim,
};

/// lib/prisma.ts instantiates this at module load. Tests that don't mock
/// '@/lib/prisma' (the pure-function suites) still trigger that constructor,
/// so it must succeed — it just never needs to do anything, because those
/// tests never call a method on it. Tests that exercise database-touching
/// code always mock '@/lib/prisma' directly instead of relying on this class.
export class PrismaClient {
  constructor(_?: unknown) {}
}
